package counter

import "sync"

// Counter counts occurrences of string keys.
type Counter struct {
	mu sync.Mutex
	m  map[string]int
}

// New returns an empty counter.
func New() *Counter { return &Counter{m: map[string]int{}} }

// Inc adds one to k.
func (c *Counter) Inc(k string) {
	c.mu.Lock()
	c.m[k]++
	c.mu.Unlock()
}

// Get returns the count for k.
func (c *Counter) Get(k string) int {
	c.mu.Lock()
	v := c.m[k]
	c.mu.Unlock()
	return v
}

// Snapshot returns the current counts.
func (c *Counter) Snapshot() map[string]int {
	c.mu.Lock()
	cp := make(map[string]int, len(c.m))
	for k, v := range c.m {
		cp[k] = v
	}
	c.mu.Unlock()
	return cp
}

