def parse(text):
    def process_value(value_str):
        if not value_str:
            return ''

        # Check for quoted value
        if value_str.startswith('"') or value_str.startswith("'"):
            quote_char = value_str[0]
            end_pos = value_str.find(quote_char, 1)
            if end_pos == -1:
